changeSet.sql:
ALTER TABLE hts_encounter
    ADD COLUMN IF NOT EXISTS last_modified_date TIMESTAMP WITHOUT TIME ZONE;

UPDATE hts_encounter
SET last_modified_date = COALESCE(date_modified, date_created)
WHERE last_modified_date IS NULL;

CREATE INDEX IF NOT EXISTS idx_hts_encounter_last_modified_date
    ON hts_encounter (last_modified_date);

-- hts_encounter: DISTINCT ON latest + window COUNT driver.
CREATE INDEX IF NOT EXISTS idx_hts_encounter_grid_latest
    ON hts_encounter (facility_id, archived, patient_uuid, id DESC);

-- hts_encounter: EXISTS semi-join in the lean count query.
CREATE INDEX IF NOT EXISTS idx_hts_encounter_grid_count
    ON hts_encounter (patient_uuid, facility_id, archived);

-- hts_encounter: NOT EXISTS on client_code = patient_person.hospital_number.
CREATE INDEX IF NOT EXISTS idx_hts_encounter_facility_arch_client_code
    ON hts_encounter (facility_id, archived, client_code);

-- hts_encounter: NOT EXISTS on CAST(patient_uuid AS text) = patient_person.uuid.
CREATE INDEX IF NOT EXISTS idx_hts_encounter_facility_arch_uuid_text
    ON hts_encounter (facility_id, archived, (CAST(patient_uuid AS text)));

-- hts_ict_encounter: grouped ict_count CTE (same skipped changeset, same root cause).
CREATE INDEX IF NOT EXISTS idx_hts_ict_encounter_grid_count
    ON hts_ict_encounter (facility_id, archived, patient_uuid);
